param([ValidateSet('git','none','plastic')][string]$Kind='git',[ValidateSet('a','b')][string]$Worker='a',[int]$Value=101,[switch]$DirtyOnly)
. "$PSScriptRoot/scalable-unity-common.ps1" -Kind $Kind
$w=(Get-Content (Join-Path $evidence ('ensure-'+$Worker+'.json')) -Raw|ConvertFrom-Json).data.workspace
$tag=$Worker+'-'+$Value
if(-not $DirtyOnly) {
$code='public static class RiValue { public static int Current => '+$Value+'; } public sealed class RiData : UnityEngine.ScriptableObject { public int Value; }'
$literal=$code|ConvertTo-Json -Compress
Eval ($tag+'-write-code') $w.path ('System.IO.File.WriteAllText(System.IO.Path.Combine(UnityEngine.Application.dataPath,"RiData.cs"),'+$literal+'); return new {pid=System.Diagnostics.Process.GetCurrentProcess().Id,wrote=true};')|Out-Null
Compile ($tag+'-compile') $w.path $Value | Out-Null
}
$edit='if (UnityEditor.SceneView.lastActiveSceneView != null) UnityEditor.SceneView.lastActiveSceneView.Focus(); var scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene(); if(scene.path!="Assets/RI.unity") { for(int i=0;i<UnityEngine.SceneManagement.SceneManager.sceneCount;i++)if(UnityEngine.SceneManagement.SceneManager.GetSceneAt(i).isDirty)throw new System.Exception("Preserve existing dirty scene before selecting RI");scene=UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/RI.unity"); } var cube=UnityEngine.GameObject.Find("RiCube"); if(cube==null) {cube=UnityEngine.GameObject.CreatePrimitive(UnityEngine.PrimitiveType.Cube);cube.name="RiCube";} cube.transform.position=new UnityEngine.Vector3(VALUE,0,0); UnityEditor.SceneManagement.EditorSceneManager.MarkSceneDirty(scene); var type=System.Type.GetType("RiData, Assembly-CSharp"); if(type==null)throw new System.Exception("Compiled RiData missing"); var asset=UnityEditor.AssetDatabase.LoadAssetAtPath("Assets/RI.asset",type); if(asset==null){asset=UnityEngine.ScriptableObject.CreateInstance(type);UnityEditor.AssetDatabase.CreateAsset(asset,"Assets/RI.asset");UnityEditor.AssetDatabase.SaveAssets();} type.GetField("Value").SetValue(asset,VALUE);UnityEditor.EditorUtility.SetDirty(asset);return new {project=System.IO.Directory.GetParent(UnityEngine.Application.dataPath).FullName,pid=System.Diagnostics.Process.GetCurrentProcess().Id,startTimeUtcTicks=System.Diagnostics.Process.GetCurrentProcess().StartTime.ToUniversalTime().Ticks,scene=scene.path,sceneDirty=scene.isDirty,assetDirty=UnityEditor.EditorUtility.IsDirty(asset),loadedCode=(int)System.Type.GetType("RiValue, Assembly-CSharp").GetProperty("Current").GetValue(null)};'
$edited=Eval ($tag+'-dirty') $w.path ($edit.Replace('VALUE',[string]$Value));$edited|ConvertTo-Json -Depth 4
if(-not $edited.sceneDirty -or -not $edited.assetDirty -or $edited.scene -ne 'Assets/RI.unity' -or $edited.loadedCode -ne $(if($DirtyOnly){1}else{$Value})){throw 'Unsaved scene/asset or actual loaded code precondition missing'}
